import socket, time, sys

HOST = 'crypto.chal.csaw.io'
PORT = 21004

class Oracle:
    """CBC padding oracle over a persistent TCP connection."""
    VALID = b"Attempting to transmit"   # valid padding
    INVALID = b"Invalid"                # bad padding

    def __init__(self, verbose=False):
        self.sock = None
        self.verbose = verbose
        self.count = 0
        self.buf = b''
        self.connect()

    def connect(self):
        try:
            self.sock.close()
        except Exception:
            pass
        self.sock = socket.create_connection((HOST, PORT), 15)
        self.sock.settimeout(15)
        self.buf = b''
        # consume banner
        self._read_until_prompt()

    def _read_until_prompt(self, timeout=15):
        """Read until the '> ' prompt appears (or timeout)."""
        deadline = time.time() + timeout
        while time.time() < deadline:
            try:
                d = self.sock.recv(4096)
            except socket.timeout:
                break
            if not d:
                break
            self.buf += d
            if self.buf.rstrip().endswith(b'>'):
                self.buf = b''
                return True
        self.buf = b''
        return False

    def query(self, ct_bytes):
        """Returns True if padding valid, False otherwise."""
        for attempt in range(3):
            try:
                self.sock.sendall(ct_bytes.hex().encode() + b'\n')
                self.count += 1
                r = self.sock.recv(4096)
                if VALID in r:
                    return True
                if INVALID in r:
                    return False
                # unexpected (banner, shutdown msg, etc.)
                if b'quit' in r or b'Goodbye' in r:
                    self.connect()
                    continue
                self.connect()
                continue
            except Exception:
                self.connect()
                continue
        raise RuntimeError('oracle failed')

    def close(self):
        try:
            self.sock.close()
        except Exception:
            pass

