                self.count += 1
                r = self.sock.recv(4096)
                if self.VALID in r:
                    return True
                if self.INVALID in r:
                    return False
                # unexpected (banner, goodbye, etc.) -> reconnect
                self.connect()
                continue
            except Exception:
                self.connect()
                continue
        raise RuntimeError('oracle failed')

    def close(self):
        try:
            self.sock.close()
        except Exception:
            pass

